import{_ as t,o as a,c as l,a3 as o}from"./chunks/framework.CWSmAuPU.js";const u=JSON.parse('{"title":"0032 安装、升级和文档只依赖 npm 源","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0032-npm-only-install.md","filePath":"reference/adr/0032-npm-only-install.md","lastUpdated":null}'),i={name:"reference/adr/0032-npm-only-install.md"};function n(s,e,d,r,c,p){return a(),l("div",null,[...e[0]||(e[0]=[o('<div><h1 id="_0032-安装、升级和文档只依赖-npm-源" tabindex="-1">0032 安装、升级和文档只依赖 npm 源 <a class="header-anchor" href="#_0032-安装、升级和文档只依赖-npm-源" aria-label="Permalink to &quot;0032 安装、升级和文档只依赖 npm 源&quot;">​</a></h1><ul><li>状态：已采纳（1.13.0-beta.1）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>req-kit 要分发给公司内网的使用者。内网有 npm 镜像，但打不开 GitHub 和部署在 Vercel、GitHub Pages 上的文档站点。过去的一键安装依赖三样外网资源：</p><ul><li>安装脚本 <code>install.sh</code> / <code>install.ps1</code> 放在文档站点上；</li><li>npm 上没有某个版本时，脚本去 GitHub 的 Release 列表找安装包；</li><li>文档只在线上站点。</li></ul><p>另外，两份脚本各自实现了检查环境、安装 Paseo、启用、配置 agent、插件这些步骤，改一处要改两处，Windows 和其他系统的行为也容易不一致。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>安装逻辑放进包里</strong>：新增 <code>req install</code>（<code>bin/bootstrap.mjs</code>，Node.js 实现），包含原来脚本的全部步骤。包新增同名命令 <code>paseo-req-kit</code>，所以任何能访问 npm 源的机器都可以直接运行 <code>npx -y paseo-req-kit@latest install</code>。</li><li><strong>镜像地址只说一次</strong>：<code>npx -y --registry=&lt;镜像&gt; … install</code>（或 <code>--registry &lt;镜像&gt;</code>）会把镜像保存为本机的 npm 源，之后的升级和 Paseo 命令行安装都走镜像；<code>--no-save-registry</code> 只用这一次。指定了镜像而镜像上没有这个版本时，直接说明可能还没同步，不再尝试 GitHub。</li><li><strong>安装脚本变薄</strong>：<code>install.sh</code> / <code>install.ps1</code> 只检查 Node.js 和 npm、选版本（npm 优先，GitHub Release 兜底），然后用 <code>npm exec</code> 运行那个版本自带的 <code>install</code>。外网用户的用法不变。</li><li><strong>文档随包发布</strong>：发布流程把文档站点构建进 npm 包（<code>site-dist/</code>），<code>req docs</code> 在本机起一个只监听 127.0.0.1 的服务并打开浏览器。文档和装的版本一致，不需要外网。</li><li>内网的共享文档站点（例如内网 Git Pages）是可选的，可以从镜像中的 npm 包取出 <code>site-dist/</code> 部署，另行实现。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>1.13 之前的版本没有 <code>install</code> 命令：新的安装脚本只能安装 1.13 及以后的版本。要装更早的版本，用那个版本标签下的旧脚本，或 <code>npm i -g paseo-req-kit@&lt;版本&gt; &amp;&amp; req setup</code>。</li><li>npm 包增加了构建好的文档站点（约几 MB）。</li><li>内网只支持 npm 方式安装和升级；git 方式仍需访问 GitHub。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0032-npm-only-install.md">docs/adr/0032-npm-only-install.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0032-npm-only-install.md">在 GitHub 上编辑</a></p>',2)])])}const h=t(i,[["render",n]]);export{u as __pageData,h as default};
